const root=process.cwd();
const queue=root+"/apps/server/cloudflare/queue";
const old=new TextDecoder().decode(Bun.spawnSync(["git","show","55e992057302ffecff406e7ff8fbde831659ed61:apps/server/cloudflare/queue/internal/dispatch.ts"],{cwd:root}).stdout);
const runtime=(await Bun.file(queue+"/runtime.ts").text()).replace('"./internal/dispatch"','"./internal/baseline-dispatch"');
let fixture=await Bun.file(queue+"/handoff-worker.fixture.ts").text();
const swaps=[['const Probe = Schema.Struct({','const Probe = Schema.Struct({ variant: Schema.Literals(["baseline","current"]),'],['const consume = makeCoreQueue(makeWorkerTelemetry(() => undefined));','const consumers={baseline:makeBaselineCoreQueue(makeWorkerTelemetry(() => undefined)),current:makeCoreQueue(makeWorkerTelemetry(() => undefined))};'],['const { ids } = yield* Schema.decodeUnknownEffect(Probe)(payload);','const { ids, variant } = yield* Schema.decodeUnknownEffect(Probe)(payload);'],['consume(batch, {','consumers[variant](batch, {']];
for(const[a,b]of swaps){if(!fixture.includes(a))throw new Error("Missing fixture anchor");fixture=fixture.replace(a,b)}
fixture='import {makeCoreQueue as makeBaselineCoreQueue} from "baseline-runtime";\n'+fixture;
const result=await Bun.build({entrypoints:[queue+"/handoff-worker.fixture.ts"],target:"browser",external:["cloudflare:workers"],plugins:[{name:"shared-control",setup(build){
 build.onResolve({filter:/^baseline-runtime$/},()=>({path:queue+"/baseline-runtime.ts"}));
 build.onResolve({filter:/baseline-dispatch$/},()=>({path:queue+"/internal/baseline-dispatch.ts"}));
 build.onLoad({filter:/baseline-runtime\.ts$/},()=>({contents:runtime,loader:"ts"}));
 build.onLoad({filter:/baseline-dispatch\.ts$/},()=>({contents:old,loader:"ts"}));
 build.onLoad({filter:/handoff-worker\.fixture\.ts$/},()=>({contents:fixture,loader:"ts"}));
}}]});if(!result.success)throw new Error(String(result.logs));await Bun.write("/tmp/fidy-handoff-sameworker.mjs",result.outputs[0]);console.log("Single Worker contains exact baseline and candidate queue dispatchers");
